# Executable task: Temperature conversion
def to_kelvin(data):
    value = data.get('value')
    unit = data.get('unit')

    if unit == 'celsius':
        kelvin = value + 273.15
    elif unit == 'fahrenheit':
        kelvin = (value - 32) * 5/9 + 273.15
    else:
        kelvin = value  # Already kelvin

    return {
        'success': True,
        'data': {
            'value': round(kelvin, 2),
            'unit': 'kelvin',
            'original': data
        }
    }

