def calculate_properties(data):
    kelvin = data.get('value')

    # Calculate water phase
    if kelvin < 273.15:
        phase = 'solid'
    elif kelvin < 373.15:
        phase = 'liquid'
    else:
        phase = 'gas'

    # Calculate thermal energy (simplified)
    thermal_energy_kj = kelvin * 8.314 / 1000  # R in kJ/(mol·K)

